// ============================================================
// FITBYTE LEAD QUALIFICATION BOT v3
// Session persistence via filesystem (survives across executions)
// ============================================================
const fs = require('fs');
const path = require('path');

const msg = $input.item.json.message;
if (!msg || !msg.text) {
  return { action: 'ignore', chatId: '', text: '' };
}

const chatId   = String(msg.chat.id);
const userId   = String(msg.from.id);
const text     = msg.text.trim();
const firstName = (msg.from.first_name || 'there');

// --- Persistent session store (one JSON file, all sessions) ---
const SESSION_FILE = '/tmp/fitbyte_sessions.json';

function loadSessions() {
  try {
    if (fs.existsSync(SESSION_FILE)) {
      return JSON.parse(fs.readFileSync(SESSION_FILE, 'utf8'));
    }
  } catch(e) {}
  return {};
}

function saveSessions(sessions) {
  fs.writeFileSync(SESSION_FILE, JSON.stringify(sessions), 'utf8');
}

const sessions = loadSessions();

// Reset on /start or no existing session
if (!sessions[userId] || text === '/start') {
  sessions[userId] = {
    step: 1,
    chatId,
    userId,
    firstName,
    answers: []
  };
  saveSessions(sessions);
  return {
    action: 'send',
    chatId,
    text: 'Hi ' + firstName + '! 👋 I\'m FitByte\'s fitness advisor.\n\nI\'ll match you with the perfect gear in 3 quick questions!\n\n*Question 1 of 3* 🎯\nWhat is your main fitness goal?\n\n① Lose weight\n② Build muscle\n③ Track performance\n④ General wellness',
    parseMode: 'Markdown'
  };
}

const session = sessions[userId];
const step = session.step;

if (step === 1) {
  session.answers.push({ q: 'Fitness goal', a: text });
  session.step = 2;
  saveSessions(sessions);
  return {
    action: 'send',
    chatId,
    text: '*Question 2 of 3* ⌚\nHow do you prefer to track your workouts?\n\n① On my wrist (smartwatch style)\n② Minimal & discreet (ring)\n③ Chest strap for maximum precision',
    parseMode: 'Markdown'
  };
}

if (step === 2) {
  session.answers.push({ q: 'Tracking preference', a: text });
  session.step = 3;
  saveSessions(sessions);
  return {
    action: 'send',
    chatId,
    text: '*Question 3 of 3* 🏋️\nHow seriously do you train?\n\n① Casual (1–2x per week)\n② Regular (3–4x per week)\n③ Athlete (5+ per week or competition)',
    parseMode: 'Markdown'
  };
}

if (step === 3) {
  session.answers.push({ q: 'Training intensity', a: text });
  session.step = 4;
  saveSessions(sessions);
  return {
    action: 'send',
    chatId,
    text: 'Almost there! 😊\n\nWhat is your *name*?',
    parseMode: 'Markdown'
  };
}

if (step === 4) {
  session.name = text;
  session.step = 5;
  saveSessions(sessions);
  return {
    action: 'send',
    chatId,
    text: 'And your *email address* so our team can reach you? 📧',
    parseMode: 'Markdown'
  };
}

if (step === 5) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(text)) {
    return {
      action: 'send',
      chatId,
      text: 'Hmm, that doesn\'t look right. 🤔\nPlease enter a valid email (e.g. name@example.com)',
      parseMode: 'Markdown'
    };
  }
  session.email = text;
  session.step = 6;
  saveSessions(sessions);

  // Hand off to classification branch
  return {
    action: 'classify',
    chatId,
    userId,
    name: session.name,
    email: session.email,
    answer1: session.answers[0] ? session.answers[0].a : '',
    answer2: session.answers[1] ? session.answers[1].a : '',
    answer3: session.answers[2] ? session.answers[2].a : '',
    timestamp: new Date().toISOString(),
    source: 'Telegram — FitByte Social Campaign'
  };
}

// Already completed
return {
  action: 'send',
  chatId,
  text: 'You already completed the quiz! 🎉 Type /start to begin again.',
  parseMode: 'Markdown'
};

const raw = ($json.message?.content || '').trim().toUpperCase().replace(/[^A-Z]/g, '');
const valid = ['WATCH', 'RING', 'CHESTBAND'];
const product = valid.includes(raw) ? raw : 'WATCH';

const lead = $('Classify or Reply?').item.json;

return {
  product,
  chatId: lead.chatId,
  userId:  lead.userId,
  name:    lead.name,
  email:   lead.email,
  answer1: lead.answer1,
  answer2: lead.answer2,
  answer3: lead.answer3,
  timestamp: lead.timestamp,
  source:    lead.source
};

// Delete session file entry for this user
const fs = require('fs');
const SESSION_FILE = '/tmp/fitbyte_sessions.json';
try {
  const sessions = JSON.parse(fs.readFileSync(SESSION_FILE, 'utf8'));
  const lead = $('Parse Product').item.json;
  delete sessions[lead.userId];
  fs.writeFileSync(SESSION_FILE, JSON.stringify(sessions), 'utf8');
} catch(e) {}

const lead = $('Parse Product').item.json;
return { chatId: lead.chatId, name: lead.name, email: lead.email };
